ption":"Live vetter class periods, current first, stored as the bare YYYY-MM period."},"liveTokenLabels":{"type":"array","items":{"type":"string","minLength":1}},"dripPerTick":{"type":"integer","minimum":1},"tickLength":{"\$ref":"#/\$defs/TickLength"},"events":{"type":"array","items":{"\$ref":"#/\$defs/StoredEvent"}}}},"PublishedConfig":{"title":"PublishedConfig","description":"The parameters exactly as they now appear in this community\'s join manifest, under vetting.ext. What an applicant and a vetter read.","type":"object","additionalProperties":false,"required":["suite","helperKey","tokenKey","vetterLabels","tokenLabels","dripPerTick","tickLength","events"],"properties":{"suite":{"type":"string","minLength":1},"helperKey":{"type":"string","minLength":1,"description":"The helper verification key, multibase — named for its role on the wire rather than for hvk."},"tokenKey":{"type":"string","minLength":1,"description":"The token verification key, multibase — named for its role on the wire rather than for tvk."},"vetterLabels":{"type":"array","items":{"type":"string","minLength":1},"description":"Class labels published whole, e.g. vetter/2026-09 — a request names one of these, not the bare period."},"tokenLabels":{"type":"array","items":{"type":"string","minLength":1}},"dripPerTick":{"type":"integer","minimum":1},"tickLength":{"\$ref":"#/\$defs/TickLength"},"events":{"type":"array","items":{"\$ref":"#/\$defs/PublishedEvent"}}}},"Response":{"\$anchor":"response","title":"VTC Vetting — Hidden — Publish — response payload","type":"object","additionalProperties":false,"required":["criterionId","stored","published","requirementsDigest"],"properties":{"criterionId":{"type":"string","minLength":1,"description":"The criterion that now accepts a hidden proof."},"stored":{"\$ref":"#/\$defs/StoredConfig"},"published":{"\$ref":"#/\$defs/PublishedConfig"},"requirementsDigest":{"type":["string","null"],"description":"The criterion\'s requirementsDigest after the change. It moves,